<script setup lang="ts">
import {ref,computed,onMounted} from 'vue'
import LionIcon from '../components/LionIcon.vue'
import ExerciseMotion from '../components/ExerciseMotion.vue'
import {loadCatalog,rankedExercises} from '../features/exercises/catalog'
import {readLegacyExerciseCatalog} from '../integrations/firestore/legacyExerciseCatalog'
import type {CatalogExercise} from '../features/exercises/catalog'
import {uiText,interfaceLanguage} from '../features/i18n/interfaceLanguage'
const all=ref<CatalogExercise[]>([]),terms=ref(''),muscle=ref(''),state=ref('Caricamento catalogo V1...'),picked=ref<CatalogExercise|null>(null),lang=ref<'it'|'en'>(interfaceLanguage.value),limit=ref(80)
onMounted(async()=>{try{all.value=await loadCatalog(readLegacyExerciseCatalog);state.value=all.value.length+' ESERCIZI'}catch(e){state.value=(e as Error).message}})
const muscles=computed(()=>[...new Set(all.value.flatMap(e=>[e.target,e.bodyPart]).filter((x):x is string=>!!x).map(x=>x.toUpperCase()))].sort())
const matches=computed(()=>rankedExercises(all.value,terms.value,muscle.value,1324))
const results=computed(()=>matches.value.slice(0,limit.value))
const title=(e:CatalogExercise)=>interfaceLanguage.value==='en'?e.name:(e.name_it||e.name)
function open(e:CatalogExercise){picked.value=e;lang.value=interfaceLanguage.value}
</script>
<template><div class="stack" style="gap:14px"><section class="panel library-header"><div class="row between"><div><h2 class="card-heading"><LionIcon name="book" :size="20"/> {{uiText("LIBRERIA ESERCIZI")}}</h2><p class="muted small" style="margin:5px 0 0">{{uiText("CATALOGO ESERCIZI CONDIVISO LION FIT")}}</p></div><span class="pill">{{uiText(state)}}</span></div><div class="library-filters"><input v-model="terms" :placeholder="uiText('Cerca in italiano o inglese (es. panca, bench)...')" @input="limit=80"/><select v-model="muscle" @change="limit=80"><option value="">{{uiText("Tutti i Muscoli")}}</option><option v-for="m in muscles" :key="m" :value="m">{{m}}</option></select></div></section>
<div class="notice notice-success library-explain">{{interfaceLanguage==='en'?'Animated exercise previews start automatically. Open an exercise for instructions and playback controls.':'Le anteprime SVG si animano automaticamente: scorri per vedere gli esercizi in movimento senza aprirli.'}}</div>
<div class="library-grid"><button v-for="(e,i) in results" :key="e.id" class="library-card" style="text-align:left;color:inherit" @click="open(e)"><ExerciseMotion v-if="e.animation?.frames?.length" :exercise="e"/><div v-else class="exercise-motion-fallback" style="min-height:110px;display:grid;place-items:center">{{uiText('📖 Solo istruzioni, senza SVG')}}</div><h3>{{title(e)}}</h3><p>EN · {{e.name}}</p><span class="green small">{{e.target?.toUpperCase()||'ESERCIZIO'}}</span><p class="small muted">{{e.bodyPart||''}} · {{e.equipment||uiText('Attrezzatura non specificata')}}</p><span v-if="terms&&i===0" class="best-result">{{uiText("★ MIGLIOR RISULTATO")}}</span></button></div>
<div v-if="!results.length" class="panel">{{uiText("Nessun esercizio trovato.")}}</div><button v-if="matches.length>limit" class="secondary" @click="limit+=80">{{uiText("Mostra altri esercizi")}} ({{limit}} / {{matches.length}})</button>
<div v-if="picked" class="modal-overlay" @click.self="picked=null"><div class="dialog exercise-dialog"><div class="row between"><h2>{{title(picked)}}</h2><button class="secondary" @click="picked=null">{{uiText("CHIUDI")}} ✕</button></div><ExerciseMotion v-if="picked.animation?.frames?.length" :exercise="picked" eager/><p v-else class="muted">{{uiText("Questo esercizio ha istruzioni testuali ma non un’animazione SVG nella libreria originale.")}}</p><p class="muted" style="margin:15px 0">EN: {{picked.name}} {{uiText("· Muscolo:")}} {{picked.target}} {{uiText("· Attrezzatura:")}} {{picked.equipment||uiText('non specificata')}}</p><p v-if="picked.secondaryMuscles?.length" class="small muted">{{uiText("Muscoli secondari:")}} {{picked.secondaryMuscles.join(', ')}}</p><p class="small muted">{{uiText("Licenza dati:")}} {{picked.dataLicense||'non indicata'}} · Media: {{picked.animation?.license||picked.mediaStatus||'non indicati'}}</p><div class="row"><button class="ghost" @click="lang=lang==='it'?'en':'it'" :disabled="!picked.instructions_it?.length">{{uiText(lang==='it'?'Mostra inglese':'Mostra italiano')}}</button></div><ol class="exercise-steps"><li v-for="(step,i) in (lang==='it'&&picked.instructions_it?.length?picked.instructions_it:picked.instructions||[])" :key="i">{{step}}</li></ol></div></div></div></template>
